CREATE TRIGGER RefCountryStates_Version_Update
	ON RefCountryStates
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RW_PK = RVC_ParentPK
